public class CreateBaggingWorkOrder
{
    public record Command(
        decimal PlannedQtyKg,
        PackagingOwnership PackagingOwnership,
        Guid OwnerId,
        Guid SourceItemId,
        Guid TargetItemId,
        Guid? SourceLotId
    ) : ICommand<Guid>;

    public class CommandValidator : AbstractValidator<Command>
    {
        public CommandValidator(ILocalizationService localizationService)
        {
            RuleFor(x => x.PlannedQtyKg).GreaterThan(0);
            RuleFor(x => x.OwnerId).NotEmpty();
            RuleFor(x => x.SourceItemId).NotEmpty();
            RuleFor(x => x.TargetItemId).NotEmpty();
        }
    }

    public class CommandHandler(
        IAppDbContext context,
        INumberSequenceService numberSequenceService,
        ILogger<CommandHandler> logger) : ICommandHandler<Command, Guid>
    {
        public async Task<Guid> HandleAsync(Command command, CancellationToken ct = default)
        {
            var bwoNumber = await numberSequenceService.NextAsync("BWO", ct);
            var entity = new BaggingWorkOrder
            {
                BwoNumber = bwoNumber,
                PlannedQtyKg = command.PlannedQtyKg,
                Status = BaggingStatus.Draft,
                PackagingOwnership = command.PackagingOwnership,
                OwnerId = command.OwnerId,
                SourceItemId = command.SourceItemId,
                TargetItemId = command.TargetItemId,
                SourceLotId = command.SourceLotId
            };
            context.BaggingWorkOrders.Add(entity);
            await context.SaveChangesAsync(ct);
            return entity.Id;
        }
    }
}

