[ApiController]
[Route("api/bagging-work-orders")]
[Authorize]
public sealed class BaggingWorkOrdersController(IDispatcher dispatcher) : ControllerBase
{
    [HttpGet]
    public async Task<IActionResult> GetList([FromQuery] int page = 1, [FromQuery] int pageSize = 10, [FromQuery] string? filter = null, [FromQuery] string? sort = null, [FromQuery] string? formCode = "OPSBWOG01", CancellationToken ct = default)
    {
        var query = new GetBaggingWorkOrderList.Query { Page = page, PageSize = pageSize, Filter = filter, Sort = sort, FormCode = formCode ?? "OPSBWOG01" };
        var result = await dispatcher.QueryAsync(query, ct);
        return Ok(ApiResult<DynamicGridResult>.Success(result));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> GetById([FromRoute] Guid id, CancellationToken ct)
    {
        var result = await dispatcher.QueryAsync(new GetBaggingWorkOrderById.Query(id), ct);
        if (result == null) return NotFound();
        return Ok(ApiResult<BaggingWorkOrderDetailDto>.Success(result));
    }

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] CreateBaggingWorkOrder.Command command, CancellationToken ct)
    {
        var id = await dispatcher.DispatchAsync(command, ct);
        return StatusCode(201, ApiResult<Guid>.Success(id));
    }

    [HttpPost("{id:guid}/complete")]
    public async Task<IActionResult> Complete(Guid id, [FromBody] CompleteBaggingWorkOrder.Command command, CancellationToken ct)
    {
        await dispatcher.DispatchAsync(command with { Id = id }, ct);
        return NoContent();
    }
}

